where not exists (
  select 1 from public.learning_paths where slug = 'introduction-to-philosophy'
);

update public.learning_paths
set
  title = 'Introduction to Philosophy',
  goal = 'Introduction to Philosophy',
  summary = 'Introduction to Philosophy treats philosophy as disciplined questioning about reality, knowledge, value, meaning, and human life. Students learn to read, evaluate, reconstruct, and write arguments, then work through knowledge and skepticism, reality and metaphysics, mind and identity, free will, God and evil, moral theory and applied dilemmas, justice, science, language, and ancient, modern, and contemporary philosophy. The course ends by turning those questions into clear claims, charitable objections, rigorous replies, and polished prose.',
  data = $iphijson${"slug": "introduction-to-philosophy", "title": "Introduction to Philosophy", "description": "Introduction to Philosophy treats philosophy as disciplined questioning about reality, knowledge, value, meaning, and human life. Students learn to read, evaluate, reconstruct, and write arguments, then work through knowledge and skepticism, reality and metaphysics, mind and identity, free will, God and evil, moral theory and applied dilemmas, justice, science, language, and ancient, modern, and contemporary philosophy. The course ends by turning those questions into clear claims, charitable objections, rigorous replies, and polished prose.", "topics": [{"id": "72b6e7ee-cde5-420a-a34e-a1827ac144d5", "type": "topic", "title": "What Philosophy Is and How Philosophers Ask Questions", "description": "Orient students to philosophy as disciplined questioning about reality, knowledge, value, meaning, and human life.", "children": [{"id": "2eadb690-d6e3-4dbe-aa9b-e599f36cc13e", "type": "subtopic", "title": "Philosophical questions", "children": [{"id": "4a73a2b2-11e8-44a8-963a-a5573d1c800d", "type": "concept", "title": "Conceptual depth"}, {"id": "1a63f64a-6ab9-4f6f-b31c-75d61a1c3d38", "type": "concept", "title": "Normative and descriptive questions"}, {"id": "d82a360b-e199-49bd-84e3-a069d91655d2", "type": "concept", "title": "First-order and second-order questions"}, {"id": "6884d1af-ef6f-4a8c-88ef-20687ff5f501", "type": "concept", "title": "Big questions and precise problems"}], "description": "Students begin by learning what makes a question philosophical: it presses beneath facts into concepts, reasons, assumptions, and values."}, {"id": "70d446f5-a868-4d03-a4dc-d87727f5166c", "type": "subtopic", "title": "Branches of philosophy", "children": [{"id": "d0dc7a78-a854-40ee-af24-c1568709755f", "type": "concept", "title": "Metaphysics"}, {"id": "97e5be0b-287e-409a-b999-69e8a573f3b2", "type": "concept", "title": "Epistemology"}, {"id": "bcc378b1-409c-46fc-a414-3a690dc2255e", "type": "concept", "title": "Ethics"}, {"id": "e68aaa5b-719d-4c4d-8c1f-a3a71e5201e7", "type": "concept", "title": "Logic and philosophy of language"}], "description": "The branches give students a map of the field without reducing philosophy to a list of isolated topics."}, {"id": "ea873198-b366-4748-8988-67f6e34561e6", "type": "subtopic", "title": "The examined life", "children": [{"id": "89d237c4-1a1b-4dcb-99da-6d4ec58dc21e", "type": "concept", "title": "Socratic questioning"}, {"id": "c217cf8d-2742-4d31-b0e1-678a702c52c3", "type": "concept", "title": "Wonder and perplexity"}, {"id": "681477f1-0e6c-4fa9-8610-e4b6ea0fef98", "type": "concept", "title": "Intellectual virtues"}, {"id": "1a970448-2da4-46ad-9f35-ceacfd408a22", "type": "concept", "title": "Philosophy beyond the classroom"}], "description": "Philosophy is also a practice of self-scrutiny, intellectual humility, and public reasoning."}]}, {"id": "cdc4d0f7-f2e1-4e72-8822-9de4b329fa07", "type": "topic", "title": "Arguments, Validity, Soundness, and Philosophical Method", "description": "Build the analytic toolkit students need to read, evaluate, reconstruct, and write philosophical arguments.", "children": [{"id": "b8948526-7687-483a-91b8-e4d8f7e41d82", "type": "subtopic", "title": "Argument reconstruction", "children": [{"id": "039f4ae3-765b-4424-8e4d-a04c35c76d00", "type": "concept", "title": "Conclusions and premises"}, {"id": "48875195-bb3f-4651-9c57-3b05cb96ea79", "type": "concept", "title": "Implicit assumptions"}, {"id": "16541e92-a82e-449a-9379-ddc821398eb1", "type": "concept", "title": "Charitable interpretation"}, {"id": "f3d2f28b-d572-4876-af4c-9bde1f8103b0", "type": "concept", "title": "Standard form"}], "description": "Students learn to identify a philosopher's conclusion, premises, hidden assumptions, and inferential structure."}, {"id": "0a2ed25a-20d1-47c5-a411-0d27825eeaeb", "type": "subtopic", "title": "Deductive and inductive reasoning", "children": [{"id": "6c235b50-171d-4441-a5a0-b7a0ed9c1bc4", "type": "concept", "title": "Validity"}, {"id": "19bf7134-b3ce-4255-8d1d-2eb389b589d1", "type": "concept", "title": "Soundness"}, {"id": "70de62ff-c10d-45c0-a92d-a71369f0512a", "type": "concept", "title": "Strength and cogency"}, {"id": "058d9d21-12da-4c04-89d8-967d0eb5ea44", "type": "concept", "title": "Counterexamples"}], "description": "This subtopic gives students the difference between arguments that guarantee conclusions and arguments that support conclusions probabilistically."}, {"id": "5f99bcfc-726f-4582-9952-9d00dadb45f9", "type": "subtopic", "title": "Philosophical writing habits", "children": [{"id": "bbf48721-25a4-4b7e-a307-d38589125a13", "type": "concept", "title": "Thesis statements"}, {"id": "29725531-daa3-4e35-bbc7-a62c8c6fe0e9", "type": "concept", "title": "Objection and reply"}, {"id": "5836bfc6-a008-4795-b1ee-11f0fbdb2fe7", "type": "concept", "title": "Definitions"}, {"id": "9b63c034-6e28-4b4e-bf85-7f4bb09782ac", "type": "concept", "title": "Concise prose"}], "description": "Good philosophy depends on clarity, precision, fair objections, and disciplined revision."}]}, {"id": "51f3d556-02ae-4450-becb-cda49121803f", "type": "topic", "title": "Knowledge, Skepticism, and the Possibility of Certainty", "description": "Introduce epistemology through questions about evidence, belief, justification, doubt, and intellectual responsibility.", "children": [{"id": "e787ffd8-c8c2-49be-b0af-296435a75d47", "type": "subtopic", "title": "Knowledge and justification", "children": [{"id": "55bb2dbc-ce1a-485c-887c-5551ffb8f111", "type": "concept", "title": "Belief"}, {"id": "607ac56d-ab69-4cc9-95bb-df25afe4b66f", "type": "concept", "title": "Truth"}, {"id": "07b28bd3-4879-475d-80a4-31c44757cae9", "type": "concept", "title": "Justification"}, {"id": "12d21179-0640-467b-9768-5128a63a4ee4", "type": "concept", "title": "Gettier-style problems"}], "description": "Students ask what must be added to true belief for it to count as knowledge."}, {"id": "0cf2f335-970d-4daf-8e64-76aa8f66a97d", "type": "subtopic", "title": "Skeptical challenges", "children": [{"id": "928203fd-c0ca-4e40-9e09-9da3f7f3f0b9", "type": "concept", "title": "Dream arguments"}, {"id": "29b2415b-a5e8-480b-8ffe-aedab1804ff8", "type": "concept", "title": "External world skepticism"}, {"id": "f7f4caad-eebf-4ee6-990c-99da70c26eb6", "type": "concept", "title": "Brain-in-a-vat scenarios"}, {"id": "25c5d411-f83a-475f-b954-8a0505a6fedf", "type": "concept", "title": "Responses to skepticism"}], "description": "Skepticism tests whether our ordinary confidence in perception, memory, and inference can be defended."}, {"id": "e2f1da64-ee6a-44e0-a0e0-bf7e5051b73c", "type": "subtopic", "title": "Sources and standards of knowledge", "children": [{"id": "9a13d428-890a-48b5-a5e2-c882c9036d14", "type": "concept", "title": "Perception"}, {"id": "04a230f8-8354-4a0c-b052-f0f72e9c3593", "type": "concept", "title": "Testimony"}, {"id": "653394bb-ffe8-4c7e-bb31-5a9ea660b653", "type": "concept", "title": "Memory"}, {"id": "d3194c8f-4cc6-4d72-ab08-68bbf1af38c3", "type": "concept", "title": "A priori reasoning"}], "description": "A world-class introduction shows that different sources of belief require different kinds of evaluation."}]}, {"id": "09ea0076-0249-40a6-a744-dc1309192d61", "type": "topic", "title": "Reality, Appearance, and Metaphysical Questions", "description": "Examine what exists, what reality is like, and why ordinary appearances can be philosophically unstable.", "children": [{"id": "181dd81c-ac4f-433a-a804-04914ff07163", "type": "subtopic", "title": "Appearance and reality", "children": [{"id": "afa2e000-19d0-4934-8e5b-a0097c5558e8", "type": "concept", "title": "Sense perception"}, {"id": "0bdf8c38-2d84-4f48-96fe-334ecd271f63", "type": "concept", "title": "Illusion and error"}, {"id": "41f332e1-1307-4310-9aad-b934d51cb0a2", "type": "concept", "title": "Primary and secondary qualities"}, {"id": "5279a5de-da16-4506-985e-5efc623fb6a3", "type": "concept", "title": "Reality as mind-independent"}], "description": "Students learn why the world as it appears may not settle what reality is like."}, {"id": "d5f2205f-79bc-4ee0-a53e-2555987717d9", "type": "subtopic", "title": "Being, objects, and properties", "children": [{"id": "72acaf38-4ccf-4cf6-bb25-97172e411781", "type": "concept", "title": "Particulars and universals"}, {"id": "1feadecc-8902-4dc4-a7b9-0e0c597475bb", "type": "concept", "title": "Substance"}, {"id": "1c14ed91-2cd9-4ded-908e-6a3080010d04", "type": "concept", "title": "Properties"}, {"id": "873415cf-2504-4700-b310-f539f2edd9f5", "type": "concept", "title": "Identity conditions"}], "description": "Metaphysics asks what kinds of things exist and how they have the features they do."}, {"id": "5e8b7624-937f-41e5-bc0d-ac8395f78412", "type": "subtopic", "title": "Time, change, and causation", "children": [{"id": "bac9a6af-3815-4afe-bec7-10be736257d2", "type": "concept", "title": "Persistence through change"}, {"id": "8d29eaef-beed-416f-8dd4-98378e408652", "type": "concept", "title": "Temporal parts"}, {"id": "6731c46a-9890-4ab7-a6fd-55934c31c1b0", "type": "concept", "title": "Causal relations"}, {"id": "97b8f1d2-0c65-4e85-9fe9-bd851e678b07", "type": "concept", "title": "Necessity and possibility"}], "description": "Ordinary ideas of persistence and cause become puzzles when examined carefully."}]}, {"id": "f62e45a3-a859-4082-9ffc-651ed450f12f", "type": "topic", "title": "Mind, Body, Consciousness, and Personal Identity", "description": "Explore the nature of mental life, embodiment, selfhood, memory, and persistence through time.", "children": [{"id": "438e714a-184d-4720-8cc7-2254147f9860", "type": "subtopic", "title": "Mind-body problem", "children": [{"id": "819ffb61-c971-410d-8bea-226e54b9d67f", "type": "concept", "title": "Dualism"}, {"id": "70d1b554-b632-4366-9fc0-0f4831d4d891", "type": "concept", "title": "Physicalism"}, {"id": "ec80a950-0203-450b-92ba-bf8ad242efa1", "type": "concept", "title": "Functionalism"}, {"id": "4df6089a-78ab-4530-bdda-4d39395646b6", "type": "concept", "title": "Qualia"}], "description": "Students confront whether mental states are physical, nonphysical, functional, or something else."}, {"id": "e5830b99-b92d-48d8-820c-8312de7c863f", "type": "subtopic", "title": "Consciousness and experience", "children": [{"id": "7172f459-1b4c-4c6b-9f87-b2c6077e4ba1", "type": "concept", "title": "First-person perspective"}, {"id": "b456b8d8-3fd1-46c0-91e1-f39312f99168", "type": "concept", "title": "Intentionality"}, {"id": "de6239a5-b90a-464b-b0bf-b373475d912e", "type": "concept", "title": "Phenomenal consciousness"}, {"id": "16d78599-91be-4903-b3fd-abaf938b4f9d", "type": "concept", "title": "Hard problem"}], "description": "Consciousness matters because subjective experience resists easy reduction to behavior or computation."}, {"id": "9bc6db2e-15b3-41e7-9998-aa5bd79461fa", "type": "subtopic", "title": "Personal identity", "children": [{"id": "89d8638e-9c03-4f73-b0b5-02616156b2f7", "type": "concept", "title": "Memory accounts"}, {"id": "aabef511-8bb8-46e6-ba89-3c96f6be26a5", "type": "concept", "title": "Bodily continuity"}, {"id": "485a4189-6c40-4451-834e-3849b9c38b5e", "type": "concept", "title": "Psychological continuity"}, {"id": "08a65ae4-6fc0-48da-ac25-d34628e03d43", "type": "concept", "title": "Narrative identity"}], "description": "Identity over time asks what makes a person the same person despite bodily, psychological, and social change."}]}, {"id": "0e4d7e93-a7e4-4a7c-8ed2-a0bf416563fb", "type": "topic", "title": "Free Will, Agency, and Moral Responsibility", "description": "Ask whether human beings act freely and what freedom means for praise, blame, law, and self-understanding.", "children": [{"id": "dddce204-d1a5-4e58-b07e-c097ec8bc5a9", "type": "subtopic", "title": "Freedom and determinism", "children": [{"id": "3f5345b1-b670-47a4-a52e-53bb5c1686e3", "type": "concept", "title": "Determinism"}, {"id": "1e50ca02-7534-411d-9064-a290b3c1037d", "type": "concept", "title": "Indeterminism"}, {"id": "8eb58af2-d8c1-41e6-a88a-66ba3ff9d368", "type": "concept", "title": "Compatibilism"}, {"id": "c3871a10-fe00-4d1b-9180-7cdb7f769f6b", "type": "concept", "title": "Libertarian free will"}], "description": "Students ask whether freedom is compatible with a causally ordered universe."}, {"id": "c1b54dd1-b05d-47ec-bf0e-afc2f945d94e", "type": "subtopic", "title": "Agency and choice", "children": [{"id": "d0a25fcb-9b0a-4b59-a1d0-e0333188e58f", "type": "concept", "title": "Reasons for action"}, {"id": "b71adf17-db0d-4e86-9791-03160e68afcc", "type": "concept", "title": "Intention"}, {"id": "48a10d3a-63f5-403e-af43-e52690338f32", "type": "concept", "title": "Self-control"}, {"id": "e1e0735f-9deb-4553-9100-4f8fb3f1c9fa", "type": "concept", "title": "Practical deliberation"}], "description": "Agency shifts the topic from abstract freedom to reasons, intentions, habits, and control."}, {"id": "c936c6fd-0bd8-460a-9839-9646ec7e7905", "type": "subtopic", "title": "Responsibility and blame", "children": [{"id": "18470b81-7048-49ae-96f8-653bcdbc6314", "type": "concept", "title": "Praise and blame"}, {"id": "73d3158c-9954-4202-99ff-cc3bf3f074da", "type": "concept", "title": "Excuses"}, {"id": "a1cd5360-6432-463b-8e23-72a6bbfb5396", "type": "concept", "title": "Coercion"}, {"id": "05e6d6cd-c5ce-4c71-9335-e73218640446", "type": "concept", "title": "Legal responsibility"}], "description": "Moral responsibility connects free will to ethics, punishment, forgiveness, and social life."}]}, {"id": "f2173bb2-125d-432c-bc85-33adf173e0d1", "type": "topic", "title": "God, Evil, Faith, and Reason", "description": "Study classical and contemporary arguments about God, religious belief, evil, and the limits of reason.", "children": [{"id": "42e65d0a-4a46-4757-8664-da55a0e0cf39", "type": "subtopic", "title": "Arguments for God's existence", "children": [{"id": "ad52d1aa-aa54-46a3-90a7-685427e68a15", "type": "concept", "title": "Cosmological argument"}, {"id": "586a5fe5-a56d-45d6-96dd-94e5c4cbe331", "type": "concept", "title": "Ontological argument"}, {"id": "7a900586-4338-456d-9532-2a30cc91c0f0", "type": "concept", "title": "Design argument"}, {"id": "2cc65a35-672f-460b-8516-7681d0c28517", "type": "concept", "title": "Moral argument"}], "description": "Classical arguments teach students how metaphysical, causal, moral, and design reasoning work."}, {"id": "9b34318b-12dc-40af-9c03-4ad5e6cacc08", "type": "subtopic", "title": "Problem of evil", "children": [{"id": "3a17a465-0a63-42b2-a19c-278bd3a8a6d7", "type": "concept", "title": "Logical problem"}, {"id": "1e22531b-7b95-41c1-ae5c-95dfc17583da", "type": "concept", "title": "Evidential problem"}, {"id": "2af844e7-3213-47b0-a0b2-401c5b2f89cb", "type": "concept", "title": "Free will defense"}, {"id": "174a9bbd-075a-428a-93af-c3f299162215", "type": "concept", "title": "Soul-making responses"}], "description": "The problem of evil asks whether suffering is compatible with an all-powerful, all-knowing, perfectly good God."}, {"id": "946e51e6-8ec9-4c1f-bf33-a72695700f9f", "type": "subtopic", "title": "Faith, reason, and religious diversity", "children": [{"id": "d7bbb0f4-77a6-4184-b8f2-d6303475f7d1", "type": "concept", "title": "Fideism"}, {"id": "b7275ab9-b566-4a3a-82fc-7de87f905194", "type": "concept", "title": "Evidentialism"}, {"id": "07eef3ab-be6e-4d54-a2f2-d5488909ad23", "type": "concept", "title": "Religious experience"}, {"id": "533165bb-d6b1-4aa5-b895-117a586cfa2f", "type": "concept", "title": "Pluralism"}], "description": "Students examine whether religious belief needs evidence and how pluralism changes the debate."}]}, {"id": "9fedcc75-80a2-4179-a0cd-2e76021846ce", "type": "topic", "title": "Ethics: Consequences, Duties, Virtues, and Care", "description": "Compare major moral theories and learn how each explains right action, good character, and human flourishing.", "children": [{"id": "e314974f-c4c6-4850-adf3-a724f49d90aa", "type": "subtopic", "title": "Consequentialism", "children": [{"id": "faed1405-b47b-4e5d-ab5e-da9f96ca9ed2", "type": "concept", "title": "Utilitarianism"}, {"id": "dca10bb7-f8c5-4330-8896-f73a5e8061b7", "type": "concept", "title": "Act and rule consequentialism"}, {"id": "5bbcf07a-da4d-4f83-bce8-9bee61ba20b3", "type": "concept", "title": "Utility and preference"}, {"id": "e957405c-32df-48e1-aacc-b14fc26f01e3", "type": "concept", "title": "Demandingness objections"}], "description": "Consequentialist theories evaluate action by outcomes and force students to think carefully about welfare and aggregation."}, {"id": "de93d950-812a-4e60-a0a6-5ff78ee07111", "type": "subtopic", "title": "Deontology", "children": [{"id": "c66c7fbc-b045-41fe-92fd-d748a92c8d74", "type": "concept", "title": "Categorical imperative"}, {"id": "b03ff406-e202-4510-8187-de50120fbc80", "type": "concept", "title": "Universalizability"}, {"id": "564f98d5-5e6c-44a3-b0ce-1fb219eba616", "type": "concept", "title": "Persons as ends"}, {"id": "4643c461-18ca-4c2a-8785-b8ce92c7abca", "type": "concept", "title": "Rights and duties"}], "description": "Deontological theories teach the importance of duties, rights, respect, and constraints on what may be done to persons."}, {"id": "85a8f675-0d1c-4fc1-9edf-1c43b12fdb7a", "type": "subtopic", "title": "Virtue and care ethics", "children": [{"id": "9b7c0f54-5fa6-4f6d-afa2-504e07faafb2", "type": "concept", "title": "Virtue"}, {"id": "c51f9c78-7eaf-4f2a-b424-b5f43f2e973f", "type": "concept", "title": "Practical wisdom"}, {"id": "09688a5b-0e7a-4041-aa0a-ca3f15b935c2", "type": "concept", "title": "Care and relationality"}, {"id": "fcb289a9-493c-4225-8809-2eb8f2931124", "type": "concept", "title": "Human flourishing"}], "description": "These approaches shift attention from isolated acts to character, relationships, emotions, dependency, and flourishing."}]}, {"id": "d61241d6-0cb3-4cbe-8ddb-218f3e9e1bb1", "type": "topic", "title": "Applied Ethics and Moral Dilemmas", "description": "Practice using ethical theory on concrete controversies where values, harms, rights, and duties collide.", "children": [{"id": "78a2b623-de93-48d1-b0f2-e0ef506bc588", "type": "subtopic", "title": "Bioethics and medical decisions", "children": [{"id": "97f1caa2-6056-40bb-8447-574bcafc1519", "type": "concept", "title": "Informed consent"}, {"id": "ca2949e8-5815-4eea-a89c-e28e0f4d2d19", "type": "concept", "title": "End-of-life care"}, {"id": "0b13cf85-f26c-4b20-b849-67a23da31989", "type": "concept", "title": "Public health"}, {"id": "b14ae4fb-d0d5-486b-aa9a-a782eacb1e7c", "type": "concept", "title": "Reproductive ethics"}], "description": "Bioethics shows how autonomy, harm, beneficence, justice, and dignity shape urgent practical decisions."}, {"id": "f69b8738-97d3-4b86-8049-e4ef0e81adc1", "type": "subtopic", "title": "Technology and environmental ethics", "children": [{"id": "39756bab-ec88-49d9-97a5-007d88308387", "type": "concept", "title": "AI and automation"}, {"id": "c24c19b5-6424-421a-9082-4edea53fcc1a", "type": "concept", "title": "Privacy and surveillance"}, {"id": "0546a99b-d046-4c20-b8e0-deb457cf894b", "type": "concept", "title": "Climate responsibility"}, {"id": "f974f41f-1fe8-4297-837f-f40d8ac498fb", "type": "concept", "title": "Animal ethics"}], "description": "Modern life raises ethical questions about risk, responsibility, future generations, and nonhuman nature."}, {"id": "4e6ab4c3-199d-4ed5-a73e-27914b2af95f", "type": "subtopic", "title": "Moral disagreement", "children": [{"id": "6a0f2135-0f8e-4d26-8f39-aa232f89cc62", "type": "concept", "title": "Value conflict"}, {"id": "80409397-4dd5-406a-bf12-01f4b1eae8fb", "type": "concept", "title": "Moral uncertainty"}, {"id": "7c212323-cf6f-4fbc-9ecb-f310297e284c", "type": "concept", "title": "Pluralism"}, {"id": "2dbbf0fe-9ef6-430f-8380-1e27e79a1770", "type": "concept", "title": "Public justification"}], "description": "Applied dilemmas teach students how to reason with people who share facts but differ in values or priorities."}]}, {"id": "1f80b3df-964f-4580-a1b3-487b0eba0180", "type": "topic", "title": "Justice, Political Authority, Rights, and the Good Society", "description": "Connect moral reasoning to questions about power, law, freedom, equality, democracy, and social obligation.", "children": [{"id": "bedd0529-be28-4706-9db0-6469b7edf8e0", "type": "subtopic", "title": "Political authority", "children": [{"id": "b8fed51b-8bd9-4771-a0b8-f73a60d526bb", "type": "concept", "title": "Consent"}, {"id": "420fa85e-2593-43d9-8dea-e862e818b045", "type": "concept", "title": "Legitimacy"}, {"id": "482784cd-4cab-4f3a-9d0d-f02d6ae09790", "type": "concept", "title": "Anarchism"}, {"id": "95d9c754-6366-45cb-8562-524e8851bc15", "type": "concept", "title": "Civil disobedience"}], "description": "Students ask why anyone has the right to rule and why citizens should obey laws."}, {"id": "d34d4091-fd60-4aed-8e7e-f413b65aa566", "type": "subtopic", "title": "Justice and equality", "children": [{"id": "6dff32b5-09d9-4c75-b2d8-e1c14158d529", "type": "concept", "title": "Rawlsian justice"}, {"id": "23e935fb-e04b-4401-a690-3ddbbe62769a", "type": "concept", "title": "Libertarianism"}, {"id": "fa4ddd7b-b0c2-465f-9726-71bf22914681", "type": "concept", "title": "Capabilities"}, {"id": "b3945a7e-51b1-4470-b3d0-ce1e1697ed94", "type": "concept", "title": "Equality of opportunity"}], "description": "Theories of justice explain how benefits, burdens, rights, and opportunities should be distributed."}, {"id": "420bf998-0f61-4d57-89cd-6c46cea58d3b", "type": "subtopic", "title": "Rights, liberty, and democracy", "children": [{"id": "5e673eba-3160-4daa-b309-1101c21756fb", "type": "concept", "title": "Negative and positive liberty"}, {"id": "692a8aa7-e122-4eac-89e5-efc1c8934200", "type": "concept", "title": "Human rights"}, {"id": "5cc9ded3-7a9d-4e14-b87d-0c72829271b4", "type": "concept", "title": "Democratic legitimacy"}, {"id": "268df045-5917-4e43-b283-01e8119986f3", "type": "concept", "title": "Freedom of speech"}], "description": "Political philosophy helps students evaluate conflicts between individual freedom and collective decision-making."}]}, {"id": "2fc43538-452e-4dfb-8119-96b12030f028", "type": "topic", "title": "Science, Explanation, Causation, and Reality", "description": "Investigate how science explains the world and what its methods imply about truth, causation, objectivity, and models.", "children": [{"id": "a0f9befc-0efb-4670-a261-f92e8a75efa7", "type": "subtopic", "title": "Scientific explanation", "children": [{"id": "7c0fd79c-c5d8-40e1-8a19-7d07782c31ae", "type": "concept", "title": "Laws"}, {"id": "58c319f6-d2b5-4bb3-99b7-b0aecf6b9a0d", "type": "concept", "title": "Models"}, {"id": "d72fcf85-a298-427d-8286-1b3496ab2450", "type": "concept", "title": "Mechanisms"}, {"id": "82becdaa-c5e9-4e0a-acef-55e53828a6a0", "type": "concept", "title": "Unification"}], "description": "Students examine what makes an explanation scientific and why explanation is not just prediction."}, {"id": "142452bb-1aea-4b16-bd92-adea82630c51", "type": "subtopic", "title": "Causation and evidence", "children": [{"id": "80ec024d-0354-46a2-878c-07a97cec9060", "type": "concept", "title": "Correlation and causation"}, {"id": "35f12695-d06c-464d-b314-c6272ecbe4f3", "type": "concept", "title": "Experiments"}, {"id": "5e257054-0b9c-411c-af3b-e7faf274e5d1", "type": "concept", "title": "Counterfactuals"}, {"id": "a2528d30-3dba-4f81-af79-c31bc2cb957c", "type": "concept", "title": "Inference to the best explanation"}], "description": "Science depends on causal claims, but causation is philosophically complex."}, {"id": "eb2363a8-bb63-4dea-83a5-89ea419f52f3", "type": "subtopic", "title": "Realism and objectivity", "children": [{"id": "0ae5891a-63a6-4ad1-8872-145639094703", "type": "concept", "title": "Scientific realism"}, {"id": "865c93d3-7ed8-4f0d-b063-aa0b204ffdd1", "type": "concept", "title": "Instrumentalism"}, {"id": "a325ace3-c27f-4510-a7e6-c06be15f123a", "type": "concept", "title": "Theory-ladenness"}, {"id": "637be910-23c5-47c7-bcd3-aac484e44960", "type": "concept", "title": "Values in science"}], "description": "This subtopic asks whether successful scientific theories reveal reality or merely organize experience."}]}, {"id": "b14222f7-328b-4d38-a942-57f8e11ad33f", "type": "topic", "title": "Language, Meaning, Interpretation, and Concepts", "description": "Introduce the philosophical study of meaning, reference, definition, ambiguity, interpretation, and conceptual analysis.", "children": [{"id": "9b9b2534-d894-4cad-897c-6ebbbe3cc431", "type": "subtopic", "title": "Meaning and reference", "children": [{"id": "5e3581ba-07f2-4879-9cd3-64ec37736310", "type": "concept", "title": "Sense and reference"}, {"id": "90592b9c-0a0a-40be-93ce-72d952add5f1", "type": "concept", "title": "Names and descriptions"}, {"id": "93caf5bf-9157-4fe8-9a4d-55e8e9f07bf5", "type": "concept", "title": "Meaning as use"}, {"id": "55b642a5-990b-4667-a05f-0f8ba37d7981", "type": "concept", "title": "Context sensitivity"}], "description": "Students learn how words connect to objects, ideas, use, and social practices."}, {"id": "e40739bf-d453-44d7-aed3-71429c060f76", "type": "subtopic", "title": "Definitions and conceptual analysis", "children": [{"id": "aff2342c-9b3c-46d7-837a-716bcc9d724f", "type": "concept", "title": "Necessary and sufficient conditions"}, {"id": "68747f9b-607c-45d8-9267-07e96a91ddc1", "type": "concept", "title": "Family resemblance"}, {"id": "fbf09b0c-c11e-40a9-bcfd-26cf40704406", "type": "concept", "title": "Conceptual engineering"}, {"id": "c0a94d05-0c5c-4dc5-8dbf-f90a3ee9acd3", "type": "concept", "title": "Borderline cases"}], "description": "Philosophical progress often depends on clarifying concepts that seem obvious until tested."}, {"id": "6bbd0b5e-dfdd-4f45-8387-ca68e92a219b", "type": "subtopic", "title": "Interpretation and communication", "children": [{"id": "2ff2aa23-68cc-4631-9d41-a3cb60fe3b9e", "type": "concept", "title": "Speaker meaning"}, {"id": "30a41127-d1ae-4559-ae6b-c4f67d5a99fd", "type": "concept", "title": "Implicature"}, {"id": "ee16446a-840b-42d0-bd33-64c681c132fb", "type": "concept", "title": "Ambiguity"}, {"id": "3810e4f6-028e-4d0e-826a-d314f0d3c61c", "type": "concept", "title": "Charity and interpretation"}], "description": "Language is a social activity, so meaning involves speakers, audiences, contexts, and norms."}]}, {"id": "c189d35e-7ffc-4908-926d-43230df27d6c", "type": "topic", "title": "Ancient Philosophy: Socrates, Plato, Aristotle, and Skeptics", "description": "Read foundational ancient texts as living arguments about virtue, knowledge, reality, nature, and the examined life.", "children": [{"id": "0b40fe99-7d87-4232-a434-4ba39249d7e2", "type": "subtopic", "title": "Socrates and the examined life", "children": [{"id": "98a70f3e-d57a-42dc-9265-9b96883d4b08", "type": "concept", "title": "Apology"}, {"id": "78d04430-cfdf-4c62-8839-2d771a6ab637", "type": "concept", "title": "Euthyphro"}, {"id": "2e46bb45-e2b0-46c9-825b-0ad4ef5939d1", "type": "concept", "title": "Elenchus"}, {"id": "d3f93cc6-4c02-4357-adaf-6b326f9cf21b", "type": "concept", "title": "Virtue and ignorance"}], "description": "Socrates models philosophy as questioning, ethical seriousness, and refusal to accept unexamined convention."}, {"id": "68d18107-2c30-437b-bd76-251d1197d04d", "type": "subtopic", "title": "Plato and Aristotle", "children": [{"id": "6bfa5f1b-2bcb-4cee-9a00-71b2d0f4513a", "type": "concept", "title": "Forms"}, {"id": "1ba1372b-ad3f-4d13-92c1-9c7510b0160f", "type": "concept", "title": "Allegory of the cave"}, {"id": "4db4fd47-d8d7-469c-821b-a599080fa564", "type": "concept", "title": "Substance and causation"}, {"id": "c2dc165d-ac2c-4585-b115-41d021c5a6f2", "type": "concept", "title": "Virtue and eudaimonia"}], "description": "Plato and Aristotle supply enduring frameworks for reality, knowledge, ethics, politics, and human flourishing."}, {"id": "307aef8a-8591-4f2a-9bec-3a2ab8c8b5a5", "type": "subtopic", "title": "Hellenistic schools", "children": [{"id": "99b644cc-c694-4265-8795-5eac02af665c", "type": "concept", "title": "Stoicism"}, {"id": "ac1ecb4e-d85d-4b7f-b1b9-184835a426cc", "type": "concept", "title": "Epicureanism"}, {"id": "092e92f6-11d7-4f2a-85bb-f9f9e04bba76", "type": "concept", "title": "Skepticism"}, {"id": "9bb3b834-d3a5-4f71-80f3-189336e8f685", "type": "concept", "title": "Ataraxia"}], "description": "Later ancient schools show philosophy as a way of life and therapy for desire, fear, and confusion."}]}, {"id": "7278bec4-6206-43e2-ae7f-dddb69b38638", "type": "topic", "title": "Modern Philosophy: Descartes, Hume, Kant, and Enlightenment Critique", "description": "Trace modern debates over reason, experience, self, causation, freedom, and the conditions of knowledge.", "children": [{"id": "394effaf-5a89-4b5b-92ac-97d3e0c6b141", "type": "subtopic", "title": "Rationalism and doubt", "children": [{"id": "e19c7b25-f5b2-48de-b7c6-a92fa060a9f1", "type": "concept", "title": "Methodic doubt"}, {"id": "41718a98-c3dc-4b98-bf7e-d13e32105726", "type": "concept", "title": "Cogito"}, {"id": "63a07b86-7a1d-4ca1-88dc-758eb76ac066", "type": "concept", "title": "Clear and distinct ideas"}, {"id": "44c9e976-cb5a-480c-8be4-af564924f440", "type": "concept", "title": "Mind-body dualism"}], "description": "Descartes teaches students how radical doubt can be used to search for secure foundations."}, {"id": "09178773-08a4-4188-9bdf-d541d257493f", "type": "subtopic", "title": "Empiricism and skepticism", "children": [{"id": "2f3ae4f7-424f-4a58-87e4-113807dc4a2e", "type": "concept", "title": "Impressions and ideas"}, {"id": "5d78855d-12f5-4439-8adc-fb65c9f38ed9", "type": "concept", "title": "Induction"}, {"id": "44016c98-72f3-4a4c-b7a0-40fef63d46eb", "type": "concept", "title": "Bundle theory"}, {"id": "f9e0310a-7a1a-4d79-8f44-be5a483e90f9", "type": "concept", "title": "Sentimentalism"}], "description": "Hume shows the power and limits of experience in explaining causation, self, induction, and morality."}, {"id": "013ed817-c33f-4180-b8e1-cb5a76cc390c", "type": "subtopic", "title": "Kant and critical philosophy", "children": [{"id": "a1ac5258-7a26-486d-bb35-b1e13a2250a5", "type": "concept", "title": "Synthetic a priori"}, {"id": "a687f917-5bc1-4576-9cf4-d775ae909874", "type": "concept", "title": "Categories"}, {"id": "54908240-c729-4d80-ad8b-52b2e32b19ea", "type": "concept", "title": "Autonomy"}, {"id": "0d74a785-693f-4e2f-a6d6-3bbe797e2874", "type": "concept", "title": "Phenomena and noumena"}], "description": "Kant reframes philosophy around the conditions that make experience, knowledge, freedom, and morality possible."}]}, {"id": "b419d431-7a6d-4318-bd0d-95d8858d1850", "type": "topic", "title": "Contemporary Philosophy, Social Critique, and Public Reason", "description": "Bring philosophy into present debates about identity, power, technology, injustice, pluralism, and public life.", "children": [{"id": "c9565a0a-ac8d-4d9d-8ec2-2743b454af1b", "type": "subtopic", "title": "Philosophy and social identity", "children": [{"id": "0ce507a0-b746-428a-89a1-a3ab2c78b821", "type": "concept", "title": "Standpoint epistemology"}, {"id": "cc332887-ce56-441e-8893-dddf8eb0bd2f", "type": "concept", "title": "Epistemic injustice"}, {"id": "2d8793e2-728d-46d1-a42a-1a768140fe22", "type": "concept", "title": "Social construction"}, {"id": "b482eb0d-fa02-4fe6-b160-5a8bdc436dcc", "type": "concept", "title": "Recognition"}], "description": "Students examine how race, gender, class, disability, and culture affect knowledge, agency, and justice."}, {"id": "d6766257-69e0-4ec7-8218-e466c5a3fe1e", "type": "subtopic", "title": "Technology and human life", "children": [{"id": "7a031541-934a-42b2-b6fd-ff1938d5b552", "type": "concept", "title": "Algorithmic bias"}, {"id": "308c7d66-7596-444c-9b67-3e81519478ca", "type": "concept", "title": "Data ethics"}, {"id": "cc8c5cf2-c368-4779-93ac-21644975848f", "type": "concept", "title": "Virtual identity"}, {"id": "b3fa2fa4-7616-4532-885e-462f95626c58", "type": "concept", "title": "Human-machine agency"}], "description": "Contemporary philosophy helps students reason about algorithmic systems, digital identity, automation, and responsibility."}, {"id": "6f82a129-6fbc-45aa-89b2-c388735c9fc2", "type": "subtopic", "title": "Public philosophy", "children": [{"id": "96df3515-14a0-4825-862c-e03a856a8ed8", "type": "concept", "title": "Civic argument"}, {"id": "45c31118-82ad-4ede-a3d7-24d3788bb51b", "type": "concept", "title": "Reasonable pluralism"}, {"id": "bdd8b338-8581-4b63-938f-f30591cd250a", "type": "concept", "title": "Public ethics"}, {"id": "f9300aa8-8e91-4cf0-b907-28f96822a754", "type": "concept", "title": "Philosophy in media"}], "description": "Public reason asks how philosophy can contribute to pluralistic democratic disagreement."}]}, {"id": "f3ffd02d-c34b-4dca-bead-f8d04d28e4ad", "type": "topic", "title": "Capstone: Writing a Philosophical Argument", "description": "Help students turn philosophical questions into clear claims, charitable objections, rigorous replies, and polished prose.", "children": [{"id": "339d9c1a-81c6-433e-acda-03d3dd8dfc69", "type": "subtopic", "title": "Question to thesis", "children": [{"id": "dd964a41-02ad-46c0-aafd-7e3148e3e573", "type": "concept", "title": "Problem framing"}, {"id": "6d0f774c-9ada-4a43-bca2-edd351b56bba", "type": "concept", "title": "Thesis precision"}, {"id": "83cda9e1-be6f-4a9e-bb04-4f21c328de3b", "type": "concept", "title": "Scope limits"}, {"id": "0c95e01d-44a9-4fdd-8b18-1dd5edf58ed7", "type": "concept", "title": "Significance"}], "description": "Students learn to narrow a broad issue into a focused philosophical problem and a defensible claim."}, {"id": "4a2836d6-76f8-4b61-80de-167ac4461aa0", "type": "subtopic", "title": "Objection and reply", "children": [{"id": "dda41584-2307-4d05-a714-f1fbe7d7da50", "type": "concept", "title": "Charitable objections"}, {"id": "cc11afd1-8994-45c0-8c65-c0701cb416f6", "type": "concept", "title": "Steel-manning"}, {"id": "f8c06351-9f98-47d4-ba99-46c8de064975", "type": "concept", "title": "Reply strategies"}, {"id": "61db5f3b-e1c1-44e4-a0fc-116f363c49bf", "type": "concept", "title": "Dialectical structure"}], "description": "A strong paper earns trust by presenting the best objection before answering it."}, {"id": "c7a06261-a8ae-41fb-8cbe-7b73e0a9df4e", "type": "subtopic", "title": "Revision and research craft", "children": [{"id": "f348595a-08d6-46e2-bf2f-9d4e69151aa6", "type": "concept", "title": "Outline and draft"}, {"id": "5639fac0-5735-47e2-99c6-d79152409191", "type": "concept", "title": "Citation practices"}, {"id": "eb2e31c6-5301-4f03-8fa3-7345c3191fa7", "type": "concept", "title": "Peer review"}, {"id": "8dd4f940-a4a6-4d1d-b544-16574944546c", "type": "concept", "title": "Final polish"}], "description": "The capstone treats philosophical writing as iterative thinking, not merely final presentation."}]}], "dbBacked": true}$iphijson$::jsonb,
